//! Compile `data/works/*.txt` into the binary.
//!
//! The generated file is a `static WORKS: &[(&str, &str)]` of `(slug, text)`
//! pairs, so the shipped executable carries the whole corpus and needs no data
//! files at runtime.  The corpus must therefore exist at *build* time; the
//! error below says how to produce it.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

fn main() {
    let corpus = Path::new("data/works");
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={}", corpus.display());

    let mut paths: Vec<PathBuf> = match std::fs::read_dir(corpus) {
        Ok(entries) => entries
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .filter(|path| path.extension().is_some_and(|ext| ext == "txt"))
            .collect(),
        Err(error) => panic!(
            "cannot read {}: {error}\n\
             The corpus is compiled into the binary, so it must be present at build time.\n\
             Generate it with: cd data && python3 split.py",
            corpus.display()
        ),
    };
    paths.sort();

    if paths.is_empty() {
        panic!(
            "no *.txt files in {}; generate them with: cd data && python3 split.py",
            corpus.display()
        );
    }

    let mut out = String::new();
    out.push_str("// @generated by build.rs — do not edit.\n");
    out.push_str("/// The complete works, compiled into the binary: (slug, text).\n");
    out.push_str("pub static WORKS: &[(&str, &str)] = &[\n");

    for path in &paths {
        println!("cargo:rerun-if-changed={}", path.display());

        // `include_str!` resolves relative to the generated file in OUT_DIR, so
        // the path has to be absolute.
        let absolute = std::fs::canonicalize(path)
            .unwrap_or_else(|error| panic!("cannot resolve {}: {error}", path.display()));
        let slug = path
            .file_stem()
            .map(|stem| stem.to_string_lossy().into_owned())
            .unwrap_or_default();

        writeln!(
            out,
            "    ({:?}, include_str!({:?})),",
            slug,
            absolute.display().to_string()
        )
        .expect("writing to a String cannot fail");
    }

    out.push_str("];\n");

    let destination = Path::new(&std::env::var("OUT_DIR").expect("OUT_DIR is set by cargo"))
        .join("embedded_corpus.rs");
    std::fs::write(&destination, out)
        .unwrap_or_else(|error| panic!("cannot write {}: {error}", destination.display()));
}
